const min = $('Your URLs and alert threshold').first().json.minPerformance;
return $input.all().map(({ json: r }) => {
  const top = (r.opportunities || [])[0];
  const perf = r.scores?.performance ?? null;
  return { json: {
    checkedAt: r.fetchedAt,
    url: r.url,
    device: r.strategy,
    performance: perf,
    seo: r.scores?.seo ?? null,
    lcpMs: r.lab?.lcpMs ?? null,
    cls: r.lab?.cls ?? null,
    realUserLcpP75: r.field?.lcpP75 ?? null,
    realUserInpP75: r.field?.inpP75 ?? null,
    coreWebVitalsPassed: r.coreWebVitalsPassed ?? null,
    topFix: top ? `${top.title} (~${top.savingsMs} ms)` : '',
    needsAttention: (perf !== null && perf < min) || r.coreWebVitalsPassed === false,
  }};
});

const bad = $input.all().map(i => i.json).filter(r => r.needsAttention);
if (!bad.length) return [];
const lines = bad.map(r => `• ${r.url} (${r.device}): performance ${r.performance}, Core Web Vitals ${r.coreWebVitalsPassed === false ? 'FAILED' : 'n/a'}${r.topFix ? `, top fix: ${r.topFix}` : ''}`);
return [{ json: { text: `:warning: ${bad.length} page(s) need attention this week\n${lines.join('\n')}` } }];
